// Normaliza o payload da Evolution. Trata apenas TEXTO e ÁUDIO.
const raw = $input.first().json.body || $input.first().json;
const data = raw.data || raw;
const key = data.key || {};

if (key.fromMe === true) return [];

const semSufixo = function (jid) { return (jid || '').replace(/@.*$/, ''); };
const ehLid = function (jid) { return typeof jid === 'string' && jid.endsWith('@lid'); };

// Telefone real: senderPn é a fonte confiável quando remoteJid vem como @lid.
let numero = '';
for (const cand of [key.senderPn, key.remoteJidAlt, key.remoteJid]) {
  if (cand && !ehLid(cand)) {
    numero = semSufixo(cand).replace(/\D/g, '');
    if (numero) break;
  }
}

// LID — identidade estável do contato no novo modelo do WhatsApp.
let lid = '';
for (const cand of [key.remoteJid, key.remoteJidAlt, key.previousRemoteJid, key.senderLid, key.participantLid]) {
  if (ehLid(cand)) { lid = semSufixo(cand); break; }
}

if (!numero && !lid) return [];

const msg = data.message || {};
let tipo = 'desconhecido';
let conteudo = null;
let mimetype = null;

if (msg.conversation) {
  tipo = 'texto';
  conteudo = msg.conversation;
} else if (msg.extendedTextMessage?.text) {
  tipo = 'texto';
  conteudo = msg.extendedTextMessage.text;
} else if (msg.audioMessage) {
  tipo = 'audio';
  mimetype = msg.audioMessage.mimetype;
} else {
  return [];
}

return [{
  json: {
    numero,
    lid,
    tipo,
    conteudo,
    mimetype,
    messageId: key.id,
    timestamp: data.messageTimestamp || Math.floor(Date.now() / 1000),
    // Carimbo do momento em que esta execução entrou — usado pelo Switch
    // do buffer pra decidir se já passaram buffer_window_seg de silêncio.
    bufferStartMs: Date.now(),
  },
}];

// Junta os dados da mensagem com os dados do cliente oculto ativo.
const msg = $('Normalizar mensagem').first().json;
const co = $input.first().json;
const eh_primeira_resposta = !co.primeira_resposta_em;

// Número de envio: prioriza o do remetente; se só veio LID, usa o cadastrado.
const normFone = function (s) {
  let d = (s || '').replace(/\D/g, '');
  if (d.length === 10 || d.length === 11) d = '55' + d;
  return d;
};
const numero_envio = msg.numero || normFone(co.clinica_whatsapp) || normFone(co.clinica_telefone);

return [{ json: { ...msg, ...co, eh_primeira_resposta, numero_envio } }];

// TODO — CONVERSÃO DE ÁUDIO. WhatsApp manda ogg/opus; OpenRouter input_audio
// só aceita "mp3" ou "wav". Ligar ffmpeg (n8n self-hosted) ou CloudConvert.
const base = $('Merge dados').first().json;
const base64 = $input.first().json.base64;
if (!base64) throw new Error('Evolution nao retornou base64 do audio');
return [{
  json: {
    ...base,
    audio_base64: base64, // TODO: substituir pelo mp3 convertido
    audio_format: 'mp3',
  },
}];

