const resp = $input.first().json;
const msg = resp.choices?.[0]?.message;
if (!msg) throw new Error('Resposta invalida do OpenRouter');

const ctx = $('Montar prompt do Carlos').first().json;
const MOTIVOS_TOOL = ['objetivos_cobertos', 'limite_turnos', 'clinica_desistiu', 'desconfianca'];

let mensagem_resposta = '';
let encerrar = false;
let motivo_encerramento = null;

if (msg.tool_calls && msg.tool_calls.length > 0) {
  const call = msg.tool_calls[0];
  if (call.function?.name === 'encerrar_conversa') {
    const args = JSON.parse(call.function.arguments);
    mensagem_resposta = args.mensagem_final;
    encerrar = true;
    motivo_encerramento = MOTIVOS_TOOL.includes(args.motivo) ? args.motivo : 'objetivos_cobertos';
  }
} else if (msg.content) {
  mensagem_resposta = msg.content.trim();
}

if (!mensagem_resposta) throw new Error('Sem mensagem para enviar');

if (ctx.total_turnos >= 20 && !encerrar) {
  encerrar = true;
  motivo_encerramento = 'limite_turnos_forcado';
}

return [{ json: { ...ctx, mensagem_resposta, encerrar, motivo_encerramento } }];

const src = $('Processar resposta IA').first().json;
const texto = (src.mensagem_resposta || '').trim();

let partes = texto.split(/\n\s*\n+/).map(function (p) { return p.trim(); }).filter(Boolean);

const MAX = 320;
const expandido = [];
for (const p of partes) {
  if (p.length <= MAX) { expandido.push(p); continue; }
  const frases = p.match(/[^.!?\n]+[.!?]*\s*/g) || [p];
  let buff = '';
  for (const f of frases) {
    if ((buff + f).length > MAX && buff) { expandido.push(buff.trim()); buff = f; }
    else { buff += f; }
  }
  if (buff.trim()) expandido.push(buff.trim());
}
partes = expandido.filter(Boolean);

if (partes.length > 4) {
  partes = partes.slice(0, 3).concat([partes.slice(3).join('\n')]);
}
if (partes.length === 0) partes = [texto || '...'];

return partes.map(function (parte, i) {
  const typing_ms = Math.min(4000, Math.max(800, parte.length * 45));
  return {
    json: {
      numero_envio: src.numero_envio,
      parte: parte,
      parte_index: i,
      total_partes: partes.length,
      typing_ms: typing_ms,
    },
  };
});

const resp = $input.first().json;
const content = resp.choices?.[0]?.message?.content || '{}';
const analise = JSON.parse(content);
return [{
  json: {
    cliente_oculto_id: $('Processar resposta IA').first().json.cliente_oculto_id,
    lead_id: $('Processar resposta IA').first().json.lead_id,
    analise,
  },
}];
